static int atmtcp_recv_control(struct atm_dev *dev, const struct atmtcp_control *msg)
{
	struct atm_vcc *vcc;

	read_lock(&vcc_sklist_lock);
	vcc = find_vcc(dev, msg->addr.sap_addr.vpi, msg->addr.sap_addr.vci);
	if (!vcc) {
		read_unlock(&vcc_sklist_lock);
		return -EUNATCH;
	}
	vcc->qos = msg->qos;
	sk_atm(vcc)->sk_err = -msg->result;
	switch (msg->type) {
	    case ATMTCP_CTRL_OPEN:
		change_bit(ATM_VF_READY,&vcc->flags);
		break;
	    case ATMTCP_CTRL_CLOSE:
		change_bit(ATM_VF_ADDR,&vcc->flags);
		break;
	    default:
		read_unlock(&vcc_sklist_lock);
		printk(KERN_ERR "atmtcp_recv_control: unknown type %d\n",
		    msg->type);
		return -EINVAL;
	}
	wake_up(sk_sleep(sk_atm(vcc)));
	read_unlock(&vcc_sklist_lock);
	return 0;
}

